+type fixtureClock struct {
+	mu     sync.Mutex
+	now    time.Time
+	timers []*fixtureTimer
+	refuse error
+}
+type fixtureTimer struct {
+	clock    *fixtureClock
+	due      time.Time
+	callback func()
+	stopped  bool
+}
+
+func (t *fixtureTimer) Stop() bool {
+	t.clock.mu.Lock()
+	defer t.clock.mu.Unlock()
+	was := !t.stopped
+	t.stopped = true
+	return was
+}
+func (c *fixtureClock) Now() time.Time { c.mu.Lock(); defer c.mu.Unlock(); return c.now }
+func (c *fixtureClock) After(ctx context.Context, d time.Duration, f func()) (ManualTimer, error) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	if err := ctx.Err(); err != nil {
+		return nil, err
+	}
+	if c.refuse != nil {
+		return nil, c.refuse
+	}
+	timer := &fixtureTimer{clock: c, due: c.now.Add(d), callback: f}
+	c.timers = append(c.timers, timer)
+	return timer, nil
+}
+func (c *fixtureClock) Advance(d time.Duration) {
+	c.mu.Lock()
+	c.now = c.now.Add(d)
+	var callbacks []func()
+	for _, t := range c.timers {
+		if !t.stopped && !t.due.After(c.now) {
+			t.stopped = true
+			callbacks = append(callbacks, t.callback)
+		}
+	}
+	c.mu.Unlock()
+	for _, callback := range callbacks {
+		callback()
+	}
+}
+func manualFixture(t *testing.T, build func(*Body), capacity ...int) (*ManualWindow, *Body, *fixtureClock) {
+	t.Helper()
+	limit := 64
+	if len(capacity) > 0 {
+		limit = capacity[0]
+	}
+	clock := &fixtureClock{now: time.Unix(1730000000, 0).UTC()}
+	body := NewBody("manual-fixture")
+	if build != nil {
+		build(body)
+	}
+	manual, err := body.NewWindow().RunManual(context.Background(), ManualWindowConfig{Size: image.Pt(400, 260), LogicalDPI: 160, EventCapacity: limit, Now: clock.Now, AfterFunc: clock.After, NewShaper: func() (shaped.Shaper, error) { return shapedgt.NewShaperWithFonts([]fs.FS{fonts.Default}), nil }})
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() {
+		if err := manual.Close(context.Background()); err != nil && !errors.Is(err, ErrManualCallback) && !errors.Is(err, ErrManualCapacity) && !errors.Is(err, ErrManualTimerUnsupported) {
+			t.Error(err)
+		}
+	})
+	return manual, body, clock
+}
+func drainManual(t *testing.T, m *ManualWindow) {
+	t.Helper()
+	for range 256 {
+		snap, err := m.Snapshot(context.Background())
+		if err != nil {
+			t.Fatal(err)
+		}
+		if snap.Events == 0 && !snap.ReadyPaint {
+			return
+		}
+		if snap.Blocked && !snap.ReadyPaint {
+			t.Fatal("blocked source")
+		}
+		if _, err = m.Step(context.Background(), 1); err != nil {
+			t.Fatal(err)
+		}
+	}
+	t.Fatal("explicit step budget exhausted")
+}
+func inputManual(t *testing.T, m *ManualWindow, input ManualInput) {
+	t.Helper()
+	if err := m.Input(context.Background(), input); err != nil {
+		t.Fatal(err)
+	}
+}
+func clickManual(t *testing.T, m *ManualWindow, pos image.Point) {
+	t.Helper()
+	inputManual(t, m, ManualInput{Type: events.MouseDown, Button: events.Left, Position: pos})
+	inputManual(t, m, ManualInput{Type: events.MouseUp, Button: events.Left, Position: pos})
+	drainManual(t, m)
+}
+func center(w Widget) image.Point {
+	box := w.AsWidget().Geom.TotalBBox
+	return box.Min.Add(box.Size().Div(2))
