// newMainStage returns a new MainStage with given type and scene contents.
// Make further configuration choices using Set* methods, which
// can be chained directly after the newMainStage call.
// Use an appropriate Run call at the end to start the Stage running.
func newMainStage(typ StageTypes, sc *Scene) *Stage {
	st := &Stage{}
	st.setType(typ)
	st.setScene(sc)
	st.popups = &stages{}
	st.popups.main = st
	st.Main = st
	return st
}

func generateHTMLBody(bd *Body) {
	if !system.GenerateHTMLArg() || ExternalParent != nil {
		return
	}
	wb := NewWidgetBase()
	ExternalParent = wb
	wb.SetOnChildAdded(func(n tree.Node) {
		fmt.Println(GenerateHTML(n.(Widget)))
		os.Exit(0)
	})
	bd.handleExternalParent()
}

// RunMainWindow creates a new main window from the body,
// runs it, starts the app's main loop, and waits for all windows
// to close. It should typically be called once by every app at
// the end of their main function. It can not be called more than
// once for one app. For secondary windows, see [Body.RunWindow].
// If you need to configure the [Stage] further, use [Body.NewWindow]
// and then [Stage.RunMain] on the resulting [Stage].
func (bd *Body) RunMainWindow() {
	generateHTMLBody(bd)
	if ExternalParent != nil {
		bd.handleExternalParent()
		return
	}
	bd.RunWindow()
	Wait()
}

// RunMain runs the stage, starts the app's main loop,
// and waits for all windows to close. It can be called instead
// of [Body.RunMainWindow] if extra configuration steps are necessary
// on the [Stage]. It can not be called more than once for one app.
// For secondary stages, see [Stage.Run].
func (st *Stage) RunMain() {
	generateHTMLBody(st.Scene.Body)
	if ExternalParent != nil {
		st.Scene.Body.handleExternalParent()
		return
	}
	st.Run()
	Wait()
}

// ExternalParent is a parent widget external to this program.
// If it is set, calls to [Body.RunWindow] before [Wait] and
// calls to [Body.RunMainWindow] and [Stage.RunMain] will add the [Body] to this
// parent instead of creating a new window. It should typically not be
// used by end users; it is used in yaegicore and for pre-rendering apps
// as HTML that can be used as a preview and for SEO purposes.
var ExternalParent Widget

// waitCalled is whether [Wait] has been called. It is used for
// [ExternalParent] logic in [Body.RunWindow].
var waitCalled bool

// RunWindow returns and runs a new [WindowStage] that is placed in
// a new system window on multi-window platforms.
// See [Body.NewWindow] to make a window without running it.
// For the first window of your app, you should typically call
// [Body.RunMainWindow] instead.
func (bd *Body) RunWindow() *Stage {
	generateHTMLBody(bd)
	if ExternalParent != nil && !waitCalled {
		bd.handleExternalParent()
		return nil
	}
	return bd.NewWindow().Run()
}

// handleExternalParent handles [ExternalParent] logic for
// [Body.RunWindow] and [Body.RunMainWindow].
func (bd *Body) handleExternalParent() {
	ExternalParent.AsWidget().AddChild(bd)
	// we must set the correct scene for each node
	bd.WalkDown(func(n tree.Node) bool {
		n.(Widget).AsWidget().Scene = bd.Scene
		return tree.Continue
	})
	// we must not get additional scrollbars here
	bd.Styler(func(s *styles.Style) {
		s.Overflow.Set(styles.OverflowVisible)
	})
}

// NewWindow returns a new [WindowStage] that is placed in
// a new system window on multi-window platforms.
// You must call [Stage.Run] or [Stage.RunMain] to run the window;
// see [Body.RunWindow] and [Body.RunMainWindow] for versions that
// automatically do so.
func (bd *Body) NewWindow() *Stage {
	ms := newMainStage(WindowStage, bd.Scene)
	ms.SetNewWindow(true)
	return ms
}

func (st *Stage) addSceneParts() {
	if st.Type != DialogStage || st.FullWindow || st.NewWindow {
		return
	}
	// TODO: convert to use [Scene.Bars] instead of parts
	sc := st.Scene
	parts := sc.newParts()
	parts.Styler(func(s *styles.Style) {
		s.Direction = styles.Column
		s.Grow.Set(0, 1)
		s.Gap.Zero()
	})
	mv := NewHandle(parts)
	mv.Styler(func(s *styles.Style) {
		s.Direction = styles.Column
	})
	mv.FinalStyler(func(s *styles.Style) {
		s.Cursor = cursors.Move
	})
	mv.SetName("move")
	mv.OnChange(func(e events.Event) {
		e.SetHandled()
		pd := e.PrevDelta()
		np := sc.SceneGeom.Pos.Add(pd)
		np.X = max(np.X, 0)
		np.Y = max(np.Y, 0)
		rw := sc.RenderWindow()
		sz := rw.SystemWindow.Size()
		mx := sz.X - int(sc.SceneGeom.Size.X)
		my := sz.Y - int(sc.SceneGeom.Size.Y)
		np.X = min(np.X, mx)
		np.Y = min(np.Y, my)
		sc.SceneGeom.Pos = np
		sc.NeedsRender()
	})
	if st.Resizable {
		rsz := NewHandle(parts)
		rsz.Styler(func(s *styles.Style) {
			s.Direction = styles.Column
			s.FillMargin = false
		})
		rsz.FinalStyler(func(s *styles.Style) {
			s.Cursor = cursors.ResizeNWSE
			s.Min.Set(units.Em(1))
		})
		rsz.SetName("resize")
		rsz.OnChange(func(e events.Event) {
			e.SetHandled()
			pd := e.PrevDelta()
			np := sc.SceneGeom.Size.Add(pd)
			minsz := 100
			np.X = max(np.X, minsz)
			np.Y = max(np.Y, minsz)
			ng := sc.SceneGeom
			ng.Size = np
			sc.Resize(ng)
		})
	}
}

// firstWindowStages creates a temporary [stages] for the first window
// to be able to get sizing information prior to having a RenderWindow,
// based on the system App Screen Size. Only adds a RenderContext.
func (st *Stage) firstWindowStages() *stages {
	ms := &stages{}
	ms.renderContext = newRenderContext()
	return ms
}

// targetScreen returns the screen to use for opening a new window
// based on Screen field, currentRenderWindow's screen, and a fallback
// default of Screen 0.
func (st *Stage) targetScreen() *system.Screen {
	if st.Screen >= 0 && st.Screen < TheApp.NScreens() {
		return TheApp.Screen(st.Screen)
	}
	if current := currentRenderWindowSnapshot(); current != nil {
		return current.SystemWindow.Screen()
	}
	return TheApp.Screen(0)
}

// configMainStage does main-stage configuration steps
func (st *Stage) configMainStage() {
	sc := st.Scene
	if st.NewWindow {
		st.FullWindow = true
	}
	if TheApp.Platform().IsMobile() {
		// If we are a new window dialog on a large single-window platform,
		// we use a modeless dialog as a substitute.
		if st.NewWindow && st.Type == DialogStage && st.Context != nil && st.Context.AsWidget().SizeClass() != SizeCompact {
			st.FullWindow = false
			st.Modal = false
			st.Scrim = false
			// Default is to add back button in this situation.
			if !st.BackButton.Valid {
				st.SetBackButton(true)
			}
		}
		// If we are on mobile, we can never have new windows.
		st.NewWindow = false
	}
	if st.FullWindow || st.NewWindow {
		st.Scrim = false
	}
	sc.makeSceneBars()
	sc.updateScene()
}

// windowSizingStages gives a new window its own temporary sizing context.
// Borrowing the current window's context races with its resize/event loop and
// incorrectly makes the new window depend on another window's geometry/DPI.
// Stages placed in an existing window continue to use that window's context.
func (st *Stage) windowSizingStages() *stages {
	current := currentRenderWindowSnapshot()
	if st.NewWindow || current == nil {
		return st.firstWindowStages()
	}
	return &current.mains
}

// runWindow runs a Window with current settings.
func (st *Stage) runWindow() *Stage {
	current := currentRenderWindowSnapshot()
	sc := st.Scene
	st.setMains(st.windowSizingStages())
	st.configMainStage()
	st.addSceneParts()

	sz := st.renderContext.geom.Size
	// Mobile windows must take up the whole window
	// and thus don't consider pref size.
	// Desktop new windows and non-full windows can pref size.
	if !TheApp.Platform().IsMobile() &&
		(st.NewWindow || !st.FullWindow || current == nil) {
		sz = sc.contentSize(sz)
		// On offscreen, we don't want any extra space, as we want the smallest
		// possible representation of the content.
		if TheApp.Platform() != system.Offscreen {
			sz = sz.Add(image.Pt(20, 20))
			screen := st.targetScreen()
			if screen != nil {
				st.SetScreen(screen.ScreenNumber)
				if st.NewWindow && st.UseMinSize {
					// we require windows to be at least 60% and no more than 80% of the
					// screen size by default
					scsz := screen.PixelSize
					sz = image.Pt(max(sz.X, scsz.X*6/10), max(sz.Y, scsz.Y*6/10))
					sz = image.Pt(min(sz.X, scsz.X*8/10), min(sz.Y, scsz.Y*8/10))
				}
			}
		}
	}
	st.Mains = nil // reset
	if DebugSettings.WindowRenderTrace {
		fmt.Println("MainStage.RunWindow: Window Size:", sz)
	}

	if st.NewWindow || current == nil {
		sc.Resize(math32.Geom2DInt{st.renderContext.geom.Pos, sz})
		win := st.newRenderWindow()
		mainRenderWindows.add(win)
		setCurrentRenderWindow(win)
		win.goStartEventLoop()
		return st
	}
	if st.Context != nil {
		ms := st.Context.AsWidget().Scene.Stage.Mains
		msc := ms.top().Scene
		sc.SceneGeom.Size = sz
		sc.fitInWindow(msc.SceneGeom) // does resize
		ms.push(st)
		st.setMains(ms)
	} else {
		ms := &current.mains
		msc := ms.top().Scene
		sc.SceneGeom.Size = sz
		sc.fitInWindow(msc.SceneGeom) // does resize
		ms.push(st)
		st.setMains(ms)
	}
	return st
}

// getValidContext ensures that the Context is non-nil and has a valid
// Scene pointer, using CurrentRenderWindow if the current Context is not valid.
// If CurrentRenderWindow is nil (should not happen), then it returns false and
// the calling function must bail.
func (st *Stage) getValidContext() bool {
	if st.Context == nil || st.Context.AsTree().This == nil || st.Context.AsWidget().Scene == nil {
		current := currentRenderWindowSnapshot()
		if current == nil {
			slog.Error("Stage.Run: Context is nil and CurrentRenderWindow is nil, so cannot Run", "Name", st.Name, "Title", st.Title)
			return false
		}
		st.Context = current.mains.top().Scene
	}
	return true
}

// runDialog runs a Dialog with current settings.
func (st *Stage) runDialog() *Stage {
	if !st.getValidContext() {
		return st
	}
	ctx := st.Context.AsWidget()

	// if our main stages are nil, we wait until our context is shown and then try again
	if ctx.Scene.Stage == nil || ctx.Scene.Stage.Mains == nil {
		ctx.Defer(func() {
			st.runDialog()
		})
		return st
	}

	ms := ctx.Scene.Stage.Mains

	sc := st.Scene
	if ms.renderContext.manual != nil {
		st.setMains(ms)
	}
	st.configMainStage()
	st.addSceneParts()
	sc.SceneGeom.Pos = st.Pos

	st.setMains(ms) // temporary for prefs

	sz := ms.renderContext.geom.Size
	if !st.FullWindow || st.NewWindow {
		sz = sc.contentSize(sz)
		sz = sz.Add(image.Pt(50, 50))
		if st.UseMinSize {
			// dialogs must be at least 400dp wide by default
			minx := int(ctx.Scene.Styles.UnitContext.Dp(400))
			sz.X = max(sz.X, minx)
		}
		sc.SceneGeom.Pos = sc.SceneGeom.Pos.Sub(sz.Div(2)) // center dialogs by default
		sc.Events.startFocusFirst = true                   // popup dialogs always need focus
		screen := st.targetScreen()
		if screen != nil {
			st.SetScreen(screen.ScreenNumber)
		}
	}
	if DebugSettings.WindowRenderTrace {
		slog.Info("MainStage.RunDialog", "size", sz)
	}

	if st.NewWindow {
		st.Mains = nil
		sc.Resize(math32.Geom2DInt{st.renderContext.geom.Pos, sz})
		st.Type = WindowStage            // critical: now is its own window!
		sc.SceneGeom.Pos = image.Point{} // ignore pos
		win := st.newRenderWindow()
		dialogRenderWindows.add(win)
		setCurrentRenderWindow(win)
		win.goStartEventLoop()
		return st
	}
	sc.SceneGeom.Size = sz
	sc.fitInWindow(st.renderContext.geom) // does resize
	ms.push(st)
	// st.SetMains(ms) // already set
	return st
}

func (st *Stage) newRenderWindow() *renderWindow {
	name := st.Name
	title := st.Title
	opts := &system.NewWindowOptions{
		Title:     title,
		Icon:      appIconImages(),
		Size:      st.Scene.SceneGeom.Size,
		Pos:       st.Pos,
		StdPixels: false,
		Screen:    st.Screen,
	}
	opts.Flags.SetFlag(!st.Resizable, system.FixedSize)
	opts.Flags.SetFlag(st.Maximized, system.Maximized)
	opts.Flags.SetFlag(st.Fullscreen, system.Fullscreen)
	screen := st.targetScreen()
	screenName := ""
	if screen != nil {
		screenName = screen.Name
	}
	var wgp *windowGeometry
	wgp, screen = theWindowGeometrySaver.get(title, screenName)
	if wgp != nil {
		theWindowGeometrySaver.settingStart()
		opts.Screen = screen.ScreenNumber
		opts.Size = wgp.Size
		opts.Pos = wgp.Pos
		opts.StdPixels = false
		if w := AllRenderWindows.FindName(title); w != nil { // offset from existing
			opts.Pos.X += 20
			opts.Pos.Y += 20
		}
		opts.Flags.SetFlag(wgp.Max, system.Maximized)
	}
	win := newRenderWindow(name, title, opts)
	theWindowGeometrySaver.settingEnd()
	if win == nil {
		return nil
	}
	// initialize Mains
	win.mains.renderWindow = win
	win.mains.renderContext = newRenderContext() // sets defaults according to Screen
	// note: win is not yet created by the OS and we don't yet know its actual size
	// or dpi.
	win.mains.push(st)
	st.setMains(&win.mains)
	// Publish only after snapshot readers can observe initialized window state.
	AllRenderWindows.add(win)
	return win
}

// mainHandleEvent handles main stage events
func (st *Stage) mainHandleEvent(e events.Event) {
	if st.Scene == nil {
		return
	}
	st.popups.popupHandleEvent(e)
	if e.IsHandled() || (st.popups != nil && st.popups.topIsModal()) || st.Scene == nil {
		if DebugSettings.EventTrace && e.Type() != events.MouseMove {
			fmt.Println("Event handled by popup:", e)
		}
		return
	}
	e.SetLocalOff(st.Scene.SceneGeom.Pos)
	st.Scene.Events.handleEvent(e)
}

// mainHandleEvent calls mainHandleEvent on relevant stages in reverse order.
func (sm *stages) mainHandleEvent(e events.Event) {
	n := sm.stack.Len()
	for i := n - 1; i >= 0; i-- {
		st := sm.stack.ValueByIndex(i)
		st.mainHandleEvent(e)
		if e.IsHandled() || st.Modal || st.FullWindow {
			break
		}
		if st.Type == DialogStage { // modeless dialog, by definition
			if e.HasPos() && st.Scene != nil {
				b := st.Scene.SceneGeom.Bounds()
				if e.WindowPos().In(b) { // don't propagate
					break
				}
			}
		}
	}
}

package core

import (
	"cogentcore.org/core/events"
	"context"
	"time"
)

// ManualTimer is the checked timer seam's cancellation handle. Native defaults
// still use time.AfterFunc. A replay adapter wraps its bounded Clock.AfterFunc.
type ManualTimer interface{ Stop() bool }

type manualTimer struct {
	owner      *ManualWindow
	scene      *Scene
	callback   func()
	underlying ManualTimer
	state      uint8 // 0 armed; 1 queued; 2 running; 3 retired; 4 canceled queued
}
type manualTimerEvent struct {
	events.CustomEvent
	timer *manualTimer
}

func (e *manualTimerEvent) Ready() bool                     { return true }
func (e *manualTimerEvent) Merge(events.DeferredEvent) bool { return false }
func (e *manualTimerEvent) runOwned() {
	t := e.timer
	m := t.owner
	m.mu.Lock()
	if t.state == 4 {
		t.state = 3
		delete(m.timers, t)
		m.mu.Unlock()
		return
	}
	if t.state != 1 {
		m.mu.Unlock()
		return
	}
	t.state = 2
	m.mu.Unlock()
	defer func() { m.mu.Lock(); t.state = 3; delete(m.timers, t); m.mu.Unlock() }()
	if m.lifetime.Err() != nil || t.scene == nil || t.scene.This == nil {
		return
	}
	t.callback()
	e.SetHandled()
}
func (t *manualTimer) Stop() bool {
	m := t.owner
	m.mu.Lock()
	if t.state >= 2 {
		m.mu.Unlock()
		return false
	}
	if t.state == 1 {
		// Its origin node still exists. Retain credit until dispatch/unlink so
		// repeated fire/cancel cannot create unbounded tombstones.
		t.state = 4
	} else {
		t.state = 3
		delete(m.timers, t)
	}
	underlying := t.underlying
	m.mu.Unlock()
	if underlying != nil {
		underlying.Stop()
	}
	return true
}
func (m *ManualWindow) stopTimers() {
	m.mu.Lock()
	timers := make([]*manualTimer, 0, len(m.timers))
	for t := range m.timers {
		timers = append(timers, t)
	}
	m.mu.Unlock()
	for _, t := range timers {
		t.Stop()
	}
}
func (sc *Scene) afterEvent(delay time.Duration, callback func()) ManualTimer {
	rc := sc.renderContext()
	if rc == nil || rc.manual == nil {
		return time.AfterFunc(delay, callback)
	}
	m := rc.manual
	if m.lifetime.Err() != nil {
		return nil
	}
	if m.window == nil {
		m.fail(ErrManualStartupTimer)
		return nil
	}
	t := &manualTimer{owner: m, scene: sc, callback: callback}
	m.mu.Lock()
	if len(m.timers) >= m.config.EventCapacity {
		m.mu.Unlock()
		m.fail(ErrManualCapacity)
		return nil
	}
	m.timers[t] = struct{}{}
	m.mu.Unlock()
	source := m.window.SystemWindow.Events()
	underlying, err := m.config.AfterFunc(m.lifetime, delay, func() {
		// No widget/owner callout. Admission consumes this timer's already-owned
		// credit and places work behind previously admitted ordinary native input.
		q := &source.Deque
		_ = q.SendDeferred(func() (events.DeferredEvent, error) {
			m.mu.Lock()
			defer m.mu.Unlock()
			if t.state != 0 || m.lifetime.Err() != nil {
				return nil, nil
			}
			t.state = 1
			event := &manualTimerEvent{timer: t}
			event.Typ = events.Custom
			event.SetUnique()
			event.GenTime.SetTime(m.config.Now())
			return event, nil
		})
	})
	if err != nil || manualNil(underlying) {
		t.Stop()
		if err == nil {
			err = ErrManualConfig
		}
		m.fail(err)
		return nil
	}
	m.mu.Lock()
	t.underlying = underlying
	retired := t.state == 3
	m.mu.Unlock()
	if retired {
		underlying.Stop()
	}
	return t
}

// Compile-time signature documentation for adapter authors. Conversion is
// explicit because Go method return types are invariant across timer interfaces.
var _ func(context.Context, time.Duration, func()) (ManualTimer, error)

// Scene retirement cancels that scene's pending manual deadlines even when its
// originating native window and another dialog remain alive.
func (sc *Scene) stopManualTimers() {
	if rc := sc.renderContext(); rc != nil && rc.manual != nil {
		m := rc.manual
		m.mu.Lock()
		var timers []*manualTimer
		for timer := range m.timers {
			if timer.scene == sc {
				timers = append(timers, timer)
			}
		}
		m.mu.Unlock()
		for _, timer := range timers {
			timer.Stop()
		}
	}
}
func (sc *Scene) Destroy() {
	sc.stopManualTimers()
	sc.Frame.Destroy()
}

package core

import (
	"context"
	"errors"
	"fmt"
	"image"
	"math"
	"reflect"
	"slices"
	"sync"
	"sync/atomic"
	"time"
	"unicode/utf8"

	"cogentcore.org/core/events"
	"cogentcore.org/core/events/key"
	"cogentcore.org/core/math32"
	"cogentcore.org/core/system"
	"cogentcore.org/core/system/composer"
	"cogentcore.org/core/text/shaped"
)

var (
	ErrManualConfig           = errors.New("core: invalid manual window configuration")
	ErrManualUnsupported      = errors.New("core: driver does not support manual windows")
	ErrManualBusy             = errors.New("core: concurrent or reentrant manual operation")
	ErrManualClosed           = errors.New("core: manual window closed")
	ErrManualInput            = errors.New("core: invalid manual input")
	ErrManualCapacity         = errors.New("core: manual input capacity exhausted")
	ErrManualBudget           = errors.New("core: manual step budget exhausted")
	ErrManualAsyncCreation    = errors.New("core: asynchronous window construction is unsupported in manual mode")
	ErrManualTimerUnsupported = errors.New("core: timed widget callback requires the next manual timer integration checkpoint")
	ErrManualNoFrame          = errors.New("core: no manual software frame captured")
	ErrManualStartupTimer     = errors.New("core: timer admission before manual window publication is unsupported")
	ErrManualCallback         = errors.New("core: manual callback terminated abnormally")
)

// ManualWindowConfig is immutable after admission. No implicit time advance or
// first frame occurs. Shaper must contain the caller's explicit fixture fonts.
type ManualCallbackError struct{ Value any }

func (*ManualCallbackError) Error() string { return ErrManualCallback.Error() }
func (*ManualCallbackError) Unwrap() error { return ErrManualCallback }

type ManualWindowConfig struct {
	Size          image.Point
	LogicalDPI    float32
	EventCapacity int
	Now           func() time.Time
	NewShaper     func() (shaped.Shaper, error)
	// AfterFunc must be checked/bounded and use the same clock as Now. It only
	// enqueues a callback; Step owns actual widget execution.
	AfterFunc func(context.Context, time.Duration, func()) (ManualTimer, error)
}

type manualSystemFactory interface {
	ManualWindowsOnly() bool
	NewManualWindow(*system.NewWindowOptions, system.ManualWindowOptions) (system.Window, error)
}
type manualSystemWindow interface {
	ManualExecution() bool
	ManualState() system.ManualWindowState
	FlushReadyPaint() bool
}

// ManualWindow is the sole event/frame owner. A backend must never also launch
// its eventLoop/WinLoop. Public operations refuse concurrent/reentrant use.
type ManualWindow struct {
	self     *ManualWindow
	window   *renderWindow
	config   ManualWindowConfig
	lifetime context.Context
	cancel   context.CancelFunc
	busy     atomic.Bool
	mu       sync.Mutex
	failure  error
	frames   uint64
	timers   map[*manualTimer]struct{}
}

type ManualInput struct {
	Type      events.Types
	Rune      rune
	Code      key.Codes
	Modifiers key.Modifiers
	Button    events.Buttons
	Position  image.Point
	Delta     math32.Vector2
}

type ManualSnapshot struct {
	Now         time.Time
	Events      int
	Blocked     bool
	ReadyPaint  bool
	FuturePaint bool
	NextPaint   time.Time
	Frames      uint64
	Closed      bool
	Failure     error
	Timers      int
}

type ManualStepResult struct {
	Events      int
	Frames      int
	LastType    events.Types
	LastHandled bool
}

func validateManualConfig(config ManualWindowConfig) error {
	if config.Size.X <= 0 || config.Size.Y <= 0 || config.Size.X > 32768 || config.Size.Y > 32768 || config.Size.X > 16*1024*1024/config.Size.Y || config.LogicalDPI <= 0 || config.LogicalDPI > 1920 || math.IsNaN(float64(config.LogicalDPI)) || math.IsInf(float64(config.LogicalDPI), 0) || config.EventCapacity < 4 || config.EventCapacity > 1<<20 || config.Now == nil || config.NewShaper == nil || config.AfterFunc == nil {
		return ErrManualConfig
	}
	return nil
}

func (st *Stage) RunManual(ctx context.Context, config ManualWindowConfig) (*ManualWindow, error) {
	if ctx == nil {
		return nil, ErrManualConfig
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if err := validateManualConfig(config); err != nil {
		return nil, err
	}
	if st == nil || st.Scene == nil || st.Scene.This == nil || st.Mains != nil {
		return nil, ErrManualConfig
	}
	if system.OnSystemWindowCreated != nil {
		return nil, ErrManualAsyncCreation
	}
	factory, ok := system.TheApp.(manualSystemFactory)
	if !ok || system.TheApp.Platform() != system.Offscreen {
		return nil, ErrManualUnsupported
	}
	if !factory.ManualWindowsOnly() {
		return nil, system.ErrManualWindowMode
	}
	shaper, err := config.NewShaper()
	if err != nil {
		return nil, err
	}
	if manualNil(shaper) {
		return nil, ErrManualConfig
	}
	lifetime, cancel := context.WithCancel(ctx)
	m := &ManualWindow{config: config, lifetime: lifetime, cancel: cancel, timers: make(map[*manualTimer]struct{})}
	m.self = m
	rc := &renderContext{geom: math32.Geom2DInt{Size: config.Size}, logicalDPI: config.LogicalDPI, visible: true, textShaper: shaper, manual: m}
	temporary := &stages{renderContext: rc}
	st.Type = WindowStage
	st.NewWindow = true
	st.FullWindow = true
	st.Mains = nil
	st.setMains(temporary)
	st.configMainStage()
	st.addSceneParts()
	st.Scene.Resize(rc.geom)
	m.mu.Lock()
	constructionFailure := m.failure
	m.mu.Unlock()
	if constructionFailure == nil {
		constructionFailure = ctx.Err()
	}
	if constructionFailure != nil {
		cancel()
		st.Mains = nil
		st.renderContext = nil
		return nil, constructionFailure
	}
	opts := &system.NewWindowOptions{Title: st.Title, Size: config.Size, StdPixels: false}
	var createErr error
	win := newRenderWindow(st.Name, st.Title, opts, func(opts *system.NewWindowOptions) (system.Window, error) {
		systemWindow, err := factory.NewManualWindow(opts, system.ManualWindowOptions{Now: config.Now, LogicalDPI: config.LogicalDPI})
		createErr = err
		return systemWindow, err
	})
	if win == nil {
		cancel()
		st.Mains = nil
		st.renderContext = nil
		if createErr != nil {
			return nil, createErr
		}
		return nil, ErrManualUnsupported
	}
	m.window = win
	win.manual = m
	win.mains.renderWindow = win
	win.mains.renderContext = rc
	win.mains.push(st)
	st.setMains(&win.mains)
	AllRenderWindows.add(win)
	mainRenderWindows.add(win)
	setCurrentRenderWindow(win)
	// Intentionally no goStartEventLoop, WinLoop, WindowWait or first frame.
	return m, nil
}

func (m *ManualWindow) enter(ctx context.Context, cleanup bool) error {
	if m == nil || m.self != m || ctx == nil || m.config.Now == nil || m.lifetime == nil {
		return ErrManualConfig
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if !m.busy.CompareAndSwap(false, true) {
		return ErrManualBusy
	}
	if m.window == nil && !cleanup {
		m.busy.Store(false)
		return ErrManualClosed
	}
	if !cleanup {
		if err := m.lifetime.Err(); err != nil {
			m.busy.Store(false)
			return err
		}
		m.mu.Lock()
		failure := m.failure
		m.mu.Unlock()
		if failure != nil {
			m.busy.Store(false)
			return failure
		}
	}
	return nil
}
func (m *ManualWindow) fail(err error) {
	m.mu.Lock()
	if m.failure == nil {
		m.failure = err
	}
	m.mu.Unlock()
}
func (m *ManualWindow) leave() { m.busy.Store(false) }
func (m *ManualWindow) snapshotOwned() ManualSnapshot {
	s := ManualSnapshot{Now: m.config.Now(), Frames: m.frames}
	m.mu.Lock()
	s.Failure = m.failure
	s.Timers = len(m.timers)
	m.mu.Unlock()
	if m.window == nil {
		s.Closed = true
		return s
	}
	q := &m.window.SystemWindow.Events().Deque
	q.Mu.Lock()
	s.Events = len(q.Front) + len(q.Back)
	if len(q.Front) == 0 && len(q.Back) > 0 {
		if deferred, ok := q.Back[0].(events.DeferredEvent); ok {
			s.Blocked = !deferred.Ready()
		}
	}
	q.Mu.Unlock()
	native := m.window.SystemWindow.(manualSystemWindow).ManualState()
	s.ReadyPaint = native.ReadyPaint
	s.NextPaint = native.NextPaint
	s.FuturePaint = !native.NextPaint.IsZero() && s.Now.Before(native.NextPaint)
	s.Closed = native.Closed
	return s
}
func (m *ManualWindow) Snapshot(ctx context.Context) (ManualSnapshot, error) {
	if err := m.enter(ctx, true); err != nil {
		return ManualSnapshot{}, err
	}
	defer m.leave()
	return m.snapshotOwned(), nil
}

func (m *ManualWindow) Input(ctx context.Context, input ManualInput) error {
	if err := m.enter(ctx, false); err != nil {
		return err
	}
	defer m.leave()
	if m.window.SystemWindow.IsClosed() {
		return ErrManualClosed
	}
	if !utf8.ValidRune(input.Rune) || input.Modifiers < 0 || input.Modifiers & ^(key.Modifiers(1<<key.ModifiersN)-1) != 0 || input.Position.X < math.MinInt32 || input.Position.X > math.MaxInt32 || input.Position.Y < math.MinInt32 || input.Position.Y > math.MaxInt32 {
		return ErrManualInput
	}
	units := 1
	switch input.Type {
	case events.KeyDown, events.KeyUp, events.KeyChord:
		valid := false
		for _, code := range key.CodesValues() {
			if input.Code == code {
				valid = true
				break
			}
		}
		if !valid {
			return ErrManualInput
		}
		if input.Type == events.KeyDown {
			units = 2
		}
	case events.MouseDown, events.MouseUp:
		if input.Button < 0 || input.Button >= events.ButtonsN {
			return ErrManualInput
		}
	case events.MouseMove:
	case events.Scroll:
		if math.IsNaN(float64(input.Delta.X)) || math.IsNaN(float64(input.Delta.Y)) || math.IsInf(float64(input.Delta.X), 0) || math.IsInf(float64(input.Delta.Y), 0) || math.Abs(float64(input.Delta.X)) > 1e6 || math.Abs(float64(input.Delta.Y)) > 1e6 {
			return ErrManualInput
		}
	default:
		return ErrManualInput
	}
	source := m.window.SystemWindow.Events()
	source.Deque.Mu.Lock()
	queued := len(source.Deque.Front) + len(source.Deque.Back)
	source.Deque.Mu.Unlock()
	if queued > m.config.EventCapacity-units {
		return ErrManualCapacity
	}
	switch input.Type {
	case events.KeyDown, events.KeyUp, events.KeyChord:
		source.Key(input.Type, input.Rune, input.Code, input.Modifiers)
	case events.MouseDown, events.MouseUp:
		source.MouseButton(input.Type, input.Button, input.Position, input.Modifiers)
	case events.MouseMove:
		source.MouseMove(input.Position)
	case events.Scroll:
		source.Scroll(input.Position, input.Delta)
	}
	return nil
}

func (m *ManualWindow) stepOwned() (result ManualStepResult, err error) {
	completed := false
	defer func() {
		if !completed {
			err = &ManualCallbackError{Value: recover()}
			m.fail(err)
		}
	}()
	w := m.window
	w.SystemWindow.(manualSystemWindow).FlushReadyPaint()
	event, ok := w.SystemWindow.Events().Deque.PollEvent()
	if !ok {
		completed = true
		return result, nil
	}
	result.Events = 1
	result.LastType = event.Type()
	if w.SystemWindow.IsClosed() {
		closing, ok := event.(*events.WindowEvent)
		if !ok || closing.Action != events.WinClose {
			completed = true
			return result, nil
		}
	}
	w.handleEvent(event)
	result.LastHandled = event.IsHandled()
	if event.Type() == events.WindowPaint {
		m.frames++
		result.Frames = 1
	}
	if w.flags.HasFlag(winStopEventLoop) {
		m.retireOwned()
	}
	m.mu.Lock()
	err = m.failure
	m.mu.Unlock()
	completed = true
	return result, err
}
func (m *ManualWindow) Step(ctx context.Context, maximum int) (ManualStepResult, error) {
	if maximum <= 0 {
		return ManualStepResult{}, ErrManualBudget
	}
	if err := m.enter(ctx, false); err != nil {
		return ManualStepResult{}, err
	}
	defer m.leave()
	var result ManualStepResult
	for range maximum {
		if err := ctx.Err(); err != nil {
			return result, err
		}
		step, err := m.stepOwned()
		result.Events += step.Events
		result.Frames += step.Frames
		if step.Events > 0 {
			result.LastType, result.LastHandled = step.LastType, step.LastHandled
		}
		if err != nil {
			return result, err
		}
		if step.Events == 0 || m.window == nil {
			return result, nil
		}
	}
	return result, nil
}
func (m *ManualWindow) Frame(ctx context.Context) (ManualStepResult, error) {
	if err := m.enter(ctx, false); err != nil {
		return ManualStepResult{}, err
	}
	defer m.leave()
	if m.window.SystemWindow.IsClosed() {
		return ManualStepResult{}, ErrManualClosed
	}
	// The normal queue prioritizes WindowPaint over back input. Use that same
	// route rather than calling a widget render method or draining owner posts.
	m.window.SystemWindow.(interface{ RequestPaint() }).RequestPaint()
	return m.stepOwned()
}
func (m *ManualWindow) Image(ctx context.Context) (*image.RGBA, error) {
	if err := m.enter(ctx, false); err != nil {
		return nil, err
	}
	defer m.leave()
	if m.frames == 0 {
		return nil, ErrManualNoFrame
	}
	drawer, ok := m.window.SystemWindow.Composer().(*composer.ComposerDrawer)
	if !ok {
		return nil, ErrManualUnsupported
	}
	imager, ok := drawer.Drawer.(getImager)
	if !ok {
		return nil, ErrManualUnsupported
	}
	source := imager.GetImage()
	if source == nil {
		return nil, ErrManualNoFrame
	}
	return &image.RGBA{Pix: slices.Clone(source.Pix), Stride: source.Stride, Rect: source.Rect}, nil
}
func (m *ManualWindow) retireOwned() {
	w := m.window
	if w == nil {
		return
	}
	m.cancel()
	m.stopTimers()
	defer func() {
		q := &w.SystemWindow.Events().Deque
		q.Mu.Lock()
		q.Front = nil
		q.Back = nil
		q.Mu.Unlock()
		m.mu.Lock()
		clear(m.timers)
		m.mu.Unlock()
		m.window = nil
	}()
	rc := w.renderContext()
	rc.Lock()
	defer rc.Unlock()
	w.mains.deleteAll()
}

// Close force-retires an owned manual window even after a callback failure or
// canceled window lifetime. It creates no consumer goroutine or native loop.
func (m *ManualWindow) Close(ctx context.Context) (err error) {
	if m == nil {
		return ErrManualConfig
	}
	if err := m.enter(ctx, true); err != nil {
		return err
	}
	defer m.leave()
	if m.window == nil {
		return nil
	}
	completed := false
	defer func() {
		if !completed {
			err = &ManualCallbackError{Value: recover()}
			m.fail(err)
			if m.window != nil {
				m.window.closed()
				m.retireOwned()
			}
		}
	}()
	m.window.SystemWindow.Close()
	// Dispatch actual WinClose for registry/current-window behavior, then perform
	// the eventLoop's terminal scene/resource action exactly once.
	for m.window != nil {
		step, err := m.stepOwned()
		if err != nil && m.window != nil {
			m.window.closed()
			m.retireOwned()
			completed = true
			return err
		}
		if step.Events == 0 && m.window != nil {
			m.window.closed()
			m.retireOwned()
		}
	}
	completed = true
	return nil
}
func (w *renderWindow) now() time.Time {
	if w.manual != nil {
		return w.manual.config.Now()
	}
	return time.Now()
}
func (sc *Scene) Now() time.Time {
	if sc != nil {
		if rc := sc.renderContext(); rc != nil && rc.manual != nil {
			return rc.manual.config.Now()
		}
	}
	return time.Now()
}
func (sc *Scene) allowWallTimer(name string) bool {
	if sc != nil {
		if rc := sc.renderContext(); rc != nil && rc.manual != nil {
			rc.manual.fail(fmt.Errorf("%w: %s", ErrManualTimerUnsupported, name))
			return false
		}
	}
	return true
}

// Newly generated scene events use the scene's clock; events cloned from an
// admitted source retain that original timestamp and origin by design.
func (sc *Scene) stampManualEvent(e events.Event) {
	if sc != nil {
		if rc := sc.renderContext(); rc != nil && rc.manual != nil {
			e.AsBase().GenTime.SetTime(rc.manual.config.Now())
		}
	}
}

func manualNil(value any) bool {
	if value == nil {
		return true
	}
	v := reflect.ValueOf(value)
	switch v.Kind() {
	case reflect.Pointer, reflect.Func, reflect.Chan, reflect.Interface, reflect.Map, reflect.Slice:
		return v.IsNil()
	}
	return false
}

