type fixtureClock struct {
	mu     sync.Mutex
	now    time.Time
	timers []*fixtureTimer
	refuse error
}
type fixtureTimer struct {
	clock    *fixtureClock
	due      time.Time
	callback func()
	stopped  bool
}

func (t *fixtureTimer) Stop() bool {
	t.clock.mu.Lock()
	defer t.clock.mu.Unlock()
	was := !t.stopped
	t.stopped = true
	return was
}
func (c *fixtureClock) Now() time.Time { c.mu.Lock(); defer c.mu.Unlock(); return c.now }
func (c *fixtureClock) After(ctx context.Context, d time.Duration, f func()) (ManualTimer, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if c.refuse != nil {
		return nil, c.refuse
	}
	timer := &fixtureTimer{clock: c, due: c.now.Add(d), callback: f}
	c.timers = append(c.timers, timer)
	return timer, nil
}
func (c *fixtureClock) Advance(d time.Duration) {
	c.mu.Lock()
	c.now = c.now.Add(d)
	var callbacks []func()
	for _, t := range c.timers {
		if !t.stopped && !t.due.After(c.now) {
			t.stopped = true
			callbacks = append(callbacks, t.callback)
		}
	}
	c.mu.Unlock()
	for _, callback := range callbacks {
		callback()
	}
}
func manualFixture(t *testing.T, build func(*Body), capacity ...int) (*ManualWindow, *Body, *fixtureClock) {
	t.Helper()
	limit := 64
	if len(capacity) > 0 {
		limit = capacity[0]
	}
	clock := &fixtureClock{now: time.Unix(1730000000, 0).UTC()}
	body := NewBody("manual-fixture")
	if build != nil {
		build(body)
	}
	manual, err := body.NewWindow().RunManual(context.Background(), ManualWindowConfig{Size: image.Pt(400, 260), LogicalDPI: 160, EventCapacity: limit, Now: clock.Now, AfterFunc: clock.After, NewShaper: func() (shaped.Shaper, error) { return shapedgt.NewShaperWithFonts([]fs.FS{fonts.Default}), nil }})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := manual.Close(context.Background()); err != nil && !errors.Is(err, ErrManualCallback) && !errors.Is(err, ErrManualCapacity) && !errors.Is(err, ErrManualTimerUnsupported) {
			t.Error(err)
		}
	})
	return manual, body, clock
}
func drainManual(t *testing.T, m *ManualWindow) {
	t.Helper()
	for range 256 {
		snap, err := m.Snapshot(context.Background())
		if err != nil {
			t.Fatal(err)
		}
		if snap.Events == 0 && !snap.ReadyPaint {
			return
		}
		if snap.Blocked && !snap.ReadyPaint {
			t.Fatal("blocked source")
		}
		if _, err = m.Step(context.Background(), 1); err != nil {
			t.Fatal(err)
		}
	}
	t.Fatal("explicit step budget exhausted")
}
func inputManual(t *testing.T, m *ManualWindow, input ManualInput) {
	t.Helper()
	if err := m.Input(context.Background(), input); err != nil {
		t.Fatal(err)
	}
}
func clickManual(t *testing.T, m *ManualWindow, pos image.Point) {
	t.Helper()
	inputManual(t, m, ManualInput{Type: events.MouseDown, Button: events.Left, Position: pos})
	inputManual(t, m, ManualInput{Type: events.MouseUp, Button: events.Left, Position: pos})
	drainManual(t, m)
}
func center(w Widget) image.Point {
	box := w.AsWidget().Geom.TotalBBox
	return box.Min.Add(box.Size().Div(2))
}
func TestVellumManualConstructionAndExplicitInput(t *testing.T) {
	var field *TextField
	var boundaries []rune
	m, b, c := manualFixture(t, func(b *Body) {
		field = NewTextField(b).SetText("A")
		field.Styler(func(s *styles.Style) { s.Min.Set(units.Dp(160), units.Dp(40)) })
	})
	if _, err := m.Image(context.Background()); !errors.Is(err, ErrManualNoFrame) {
		t.Fatalf("hidden frame: %v", err)
	}
	s, err := m.Snapshot(context.Background())
	if err != nil || s.Frames != 0 || s.Events == 0 || !s.ReadyPaint {
		t.Fatalf("construction %+v %v", s, err)
	}
	// No worker/loop can consume these messages. Explicit stepping alone delivers.
	runtime.Gosched()
	again, _ := m.Snapshot(context.Background())
	if again.Events != s.Events || again.Frames != 0 {
		t.Fatalf("background progress %+v -> %+v", s, again)
	}
	drainManual(t, m)
	if !b.Scene.IsVisible() || field.Scene != b.Scene {
		t.Fatalf("not shown/linked after frames")
	}
	b.Scene.EventBoundary = func(e events.Event) {
		if e.Type() == events.KeyChord {
			boundaries = append(boundaries, e.AsBase().Rune)
			if !e.Time().Equal(c.Now()) {
				t.Errorf("time %v", e.Time())
			}
		}
	}
	// Actual click hit-tests focus; typing is not a direct TextField.Send call.
	clickManual(t, m, center(field))
	if b.Scene.Events.focus != field {
		t.Fatalf("focus %T; field box %v", b.Scene.Events.focus, field.Geom.TotalBBox)
	}
	inputManual(t, m, ManualInput{Type: events.KeyChord, Rune: 'x', Code: key.CodeX})
	drainManual(t, m)
	if field.EditingState().Text != "Ax" || len(boundaries) != 1 {
		t.Fatalf("actual key routing: %+v boundaries %v", field.EditingState(), boundaries)
	}
	image1, err := m.Image(context.Background())
	if err != nil || image1.Bounds().Size() != image.Pt(400, 260) {
		t.Fatalf("image %v %v", image1, err)
	}
	old := image1.Pix[0]
	image1.Pix[0] ^= 255
	image2, err := m.Image(context.Background())
	if err != nil || image2.Pix[0] != old {
		t.Fatal("image aliases composer")
	}
	if !b.Scene.Now().Equal(c.Now()) {
		t.Fatal("scene clock differs")
	}
}
func TestVellumManualDisabledAndModalRouting(t *testing.T) {
	clicks := 0
	var disabled, live *Button
	m, b, c := manualFixture(t, func(b *Body) {
		disabled = NewButton(b).SetText("disabled")
		disabled.SetState(true, states.Disabled)
		disabled.OnClick(func(events.Event) { clicks += 100 })
		live = NewButton(b).SetText("live")
		live.OnClick(func(events.Event) { clicks++ })
	})
	drainManual(t, m)
	clickManual(t, m, center(disabled))
	if clicks != 0 {
		t.Fatal("disabled activated")
	}
	clickManual(t, m, center(live))
	if clicks != 1 {
		t.Fatalf("clicks %d", clicks)
	}
	dialog := NewBody("manual modal")
	NewText(dialog).SetText("Modal")
	dialog.NewFullDialog(b).Run()
	drainManual(t, m)
	if !dialog.Scene.Now().Equal(c.Now()) || dialog.Scene.textShaper != nil {
