	}
	clickManual(t, m, center(live))
	if clicks != 1 {
		t.Fatal("modal allowed background button")
	}
	dialog.Close()
	drainManual(t, m)
	clickManual(t, m, center(live))
	if clicks != 2 {
		t.Fatalf("after modal %d", clicks)
	}
}
func TestVellumManualFixedSoftwarePixels(t *testing.T) {
	build := func(b *Body) { NewText(b).SetText("Noto fixture 123"); NewButton(b).SetText("Apply") }
