	if !s.ReadyPaint {
		t.Fatal("explicit advance did not ready paint")
	}
	if r, err = m.Step(context.Background(), 1); err != nil || r.Frames != 1 {
		t.Fatalf("due paint %+v %v", r, err)
	}
	for range m.config.EventCapacity {
