	}
	before, _ := m.Snapshot(context.Background())
	if err = m.Input(context.Background(), ManualInput{Type: events.KeyChord, Rune: 'b', Code: key.CodeB}); !errors.Is(err, ErrManualCapacity) {
		t.Fatal(err)
	}
	after, _ := m.Snapshot(context.Background())
	if before.Events != after.Events {
		t.Fatal("capacity refusal mutated queue")
	}
}

type maliciousPanic struct{}

