package offscreen

import (
	"cogentcore.org/core/events"
	"cogentcore.org/core/system"
	"cogentcore.org/core/system/composer"
	"cogentcore.org/core/system/driver/base"
	"sync"
	"sync/atomic"
	"time"
)

// Window is the implementation of [system.Window] for the offscreen platform.
type Window struct {
	base.WindowMulti[*App, *composer.ComposerDrawer]
	manual       bool
	manualClosed atomic.Bool
	manualScreen system.Screen
	manualMu     sync.Mutex
	readyPaint   bool
	nextPaint    time.Time
}

func (w *Window) Screen() *system.Screen {
	if w.manual {
		return &w.manualScreen
	}
	return TheApp.Screen(0)
}

func (w *Window) ManualExecution() bool { return w.manual }
func (w *Window) ManualState() system.ManualWindowState {
	w.manualMu.Lock()
	defer w.manualMu.Unlock()
	return system.ManualWindowState{ReadyPaint: w.readyPaint || !w.nextPaint.IsZero() && !w.Event.Now().Before(w.nextPaint), NextPaint: w.nextPaint, Closed: w.manualClosed.Load()}
}
func (w *Window) FlushReadyPaint() bool {
	if !w.manual || w.manualClosed.Load() {
		return false
	}
	w.manualMu.Lock()
	if !w.nextPaint.IsZero() && !w.Event.Now().Before(w.nextPaint) {
		w.readyPaint = true
		w.nextPaint = time.Time{}
	}
	ready := w.readyPaint
	w.readyPaint = false
	w.manualMu.Unlock()
	if ready {
		w.Event.WindowPaint()
	}
	return ready
}
func (w *Window) RequestPaint() {
	if !w.manual {
		w.WindowMulti.Window.RequestPaint()
		return
	}
	if w.manualClosed.Load() {
		return
	}
	w.manualMu.Lock()
	w.readyPaint = true
	w.manualMu.Unlock()
}
func (w *Window) RequestPaintAfter(delay time.Duration) {
	if !w.manual {
		w.WindowMulti.Window.RequestPaintAfter(delay)
		return
	}
	if w.manualClosed.Load() {
		return
	}
	if delay <= 0 {
		w.RequestPaint()
		return
	}
	deadline := w.Event.Now().Add(delay)
	w.manualMu.Lock()
	if w.nextPaint.IsZero() || deadline.Before(w.nextPaint) {
		w.nextPaint = deadline
	}
	w.manualMu.Unlock()
}
func (w *Window) IsClosed() bool {
	if w.manual {
		return w.manualClosed.Load()
	}
	return w.WindowMulti.Window.IsClosed()
}
func (w *Window) Close() {
	if !w.manual {
		w.WindowMulti.Window.Close()
		return
	}
	if !w.manualClosed.CompareAndSwap(false, true) {
		return
	}
	w.Paint.Close()
	w.Event.Window(events.WinClose)
	w.Mu.Lock()
	defer w.Mu.Unlock()
	defer func() { w.App.RemoveWindow(w); w.Compose = nil }()
	w.CloseClean()
}

