func drain(t *testing.T, m *core.ManualWindow) {
	t.Helper()
	for range 256 {
		s, err := m.Snapshot(context.Background())
		if err != nil {
			t.Fatal(err)
		}
		if s.Events == 0 && !s.ReadyPaint {
			return
		}
		if s.Blocked && !s.ReadyPaint {
			t.Fatal("blocked originating FIFO")
		}
		if _, err = m.Step(context.Background(), 1); err != nil {
			t.Fatal(err)
		}
	}
	t.Fatal("bounded drain exhausted")
}
func TestActualCheckedClockAndSceneRouting(t *testing.T) {
	clock, err := execution.NewManualClock(time.Unix(1730000000, 0).UTC(), 32, 32)
	if err != nil {
		t.Fatal(err)
	}
	defer clock.Close()
	body := core.NewBody("approved-clock native-route")
	field := core.NewTextField(body).SetText("A")
	button := core.NewButton(body).SetText("Apply")
	longs := 0
	button.On(events.LongPressStart, func(events.Event) { longs++ })
	config := core.ManualWindowConfig{Size: image.Pt(400, 260), LogicalDPI: 160, EventCapacity: 32, Now: clock.Now, AfterFunc: func(ctx context.Context, d time.Duration, fn func()) (core.ManualTimer, error) {
		return clock.AfterFunc(ctx, d, fn)
	}, NewShaper: func() (shaped.Shaper, error) { return shapedgt.NewShaperWithFonts([]fs.FS{fonts.Default}), nil }}
	window, err := body.NewWindow().RunManual(context.Background(), config)
	if err != nil {
		t.Fatal(err)
	}
	defer window.Close(context.Background())
	drain(t, window)
	box := field.Geom.TotalBBox
	position := box.Min.Add(box.Size().Div(2))
	for _, typ := range []events.Types{events.MouseDown, events.MouseUp} {
		if err = window.Input(context.Background(), core.ManualInput{Type: typ, Button: events.Left, Position: position}); err != nil {
			t.Fatal(err)
		}
	}
	drain(t, window)
	if err = window.Input(context.Background(), core.ManualInput{Type: events.KeyChord, Rune: 'x', Code: key.CodeX}); err != nil {
		t.Fatal(err)
	}
	drain(t, window)
	if field.EditingState().Text != "Ax" {
		t.Fatal("actual scene field routing failed", field.EditingState())
	}
	box = button.Geom.TotalBBox
	position = box.Min.Add(box.Size().Div(2))
	if err = window.Input(context.Background(), core.ManualInput{Type: events.MouseDown, Button: events.Left, Position: position}); err != nil {
		t.Fatal(err)
	}
	drain(t, window)
	readiness, err := clock.ReadySnapshot()
	if err != nil || readiness.Future == 0 || !readiness.CurrentIdle() {
		t.Fatalf("armed future is current-instant idle %+v %v", readiness, err)
	}
	if longs != 0 {
		t.Fatal("timer fired without advance")
	}
	if _, err = clock.Advance(core.TimingSettings.LongPressTime); err != nil {
		t.Fatal(err)
	}
	if longs != 0 {
		t.Fatal("clock ran widget callback outside originating router")
	}
	s, err := window.Snapshot(context.Background())
	if err != nil || s.Events == 0 {
		t.Fatalf("no due routing work %+v %v", s, err)
