+package lines
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+type manualTestTimer struct{ stopped bool }
+
+func (t *manualTestTimer) Stop() bool {
+	if t == nil {
+		panic("typed nil timer used")
+	}
+	prior := !t.stopped
+	t.stopped = true
+	return prior
+}
+func testExecution(failure *error) *ManualExecution {
+	return &ManualExecution{Now: func() time.Time { return time.Unix(1700000000, 0) }, AfterFunc: func(time.Duration, func()) (Timer, error) { return &manualTestTimer{}, nil }, Failure: func(err error) { *failure = err }}
+}
+func TestVellumManualLinesAdoptionAndLease(t *testing.T) {
+	var failure error
+	ls := NewLinesExact()
+	view := ls.NewView(80)
+	execution := testExecution(&failure)
+	if err := ls.BindManualExecution(view, execution); err != nil {
+		t.Fatal(err)
+	}
+	if err := ls.BindManualExecution(view, execution); err != nil {
+		t.Fatal("same lease refused", err)
+	}
+	other := testExecution(&failure)
+	if err := ls.BindManualExecution(view, other); !errors.Is(err, ErrManualExecution) {
+		t.Fatal("foreign lease accepted", err)
+	}
+	ls.ReleaseManualExecution(other)
+	if got := ls.NewView(80); got != -1 || !errors.Is(failure, ErrManualViews) {
+		t.Fatal("foreign release removed lease", got, failure)
+	}
+	ls.DeleteView(view)
+	replacement := ls.NewView(60)
+	if replacement < 0 {
+		t.Fatal("retired lease retained")
+	}
+	if err := ls.BindManualExecution(replacement, other); err != nil {
+		t.Fatal("new origin could not adopt retired buffer", err)
+	}
+	ls.Close()
+	if ls.manualExecution != nil || len(ls.views) != 0 {
+		t.Fatal("close retained lease/views")
+	}
+}
+func TestVellumManualLinesRefusesAmbientAndSharedAdoption(t *testing.T) {
+	for _, kind := range []string{"pending", "running", "autosave", "two-views"} {
+		t.Run(kind, func(t *testing.T) {
+			ls := NewLinesExact()
+			view := ls.NewView(80)
+			var failure error
+			execution := testExecution(&failure)
+			switch kind {
+			case "pending":
+				ls.markupDelayTimer = &manualTestTimer{}
+			case "running":
+				ls.markupActive = 1
+			case "autosave":
+				ls.Autosave = true
+			case "two-views":
+				ls.NewView(80)
+			}
+			want := ErrManualAmbient
+			if kind == "two-views" {
+				want = ErrManualViews
+			}
+			if err := ls.BindManualExecution(view, execution); !errors.Is(err, want) {
+				t.Fatal(kind, err)
+			}
+			if ls.manualExecution != nil {
+				t.Fatal("refused adoption mutated origin")
+			}
+			ls.markupActive = 0
+			ls.Autosave = false
+			ls.Close()
+		})
+	}
+}
+func TestVellumManualLinesSchedulingRefusalAndTypedNil(t *testing.T) {
+	for _, kind := range []string{"error", "nil", "typed-nil"} {
+		t.Run(kind, func(t *testing.T) {
+			ls := NewLinesExact()
+			view := ls.NewView(80)
+			var failure error
+			execution := testExecution(&failure)
+			refused := errors.New("owned timer capacity")
+			execution.AfterFunc = func(time.Duration, func()) (Timer, error) {
+				switch kind {
+				case "error":
+					return nil, refused
+				case "typed-nil":
+					var timer *manualTestTimer
+					return timer, nil
+				default:
+					return nil, nil
+				}
+			}
+			if err := ls.BindManualExecution(view, execution); err != nil {
+				t.Fatal(err)
+			}
+			ls.SetString("abc")
+			ls.Highlighter.Has = true
+			ls.StartDelayedReMarkup()
+			want := ErrManualExecution
+			if kind == "error" {
+				want = refused
+			}
+			if !errors.Is(failure, want) || ls.markupDelayTimer != nil {
+				t.Fatal("refusal not recorded", failure)
+			}
+			// Nothing may later fire or call Stop through an unusable timer.
+			ls.Close()
+		})
+	}
+}
+
+func TestVellumManualLinesAmbientWorkAndAutosaveRefusal(t *testing.T) {
+	ls := NewLinesExact()
+	view := ls.NewView(80)
+	var failure error
+	execution := testExecution(&failure)
+	finish, err := ls.BeginAmbientWork()
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := ls.BindManualExecution(view, execution); !errors.Is(err, ErrManualAmbient) {
+		t.Fatal("running ambient worker adopted", err)
+	}
+	finish()
+	finish() // release is idempotent, not a capacity underflow
+	if err := ls.BindManualExecution(view, execution); err != nil {
+		t.Fatal(err)
+	}
+	if release, err := ls.BeginAmbientWork(); release != nil || !errors.Is(err, ErrManualAmbient) {
+		t.Fatal("manual ambient worker accepted", err)
+	}
+	failure = nil
+	// An unsupported flag set after adoption must not launch a filesystem worker.
+	ls.Autosave = true
+	edit := ls.InsertTextBytes(ls.EndPos(), []byte("accepted"))
+	if edit == nil || !errors.Is(failure, ErrManualAmbient) || ls.ambientActive != 0 {
+		t.Fatal("autosave worker not refused", edit, failure, ls.ambientActive)
+	}
+	if ls.String() != "accepted" {
+		t.Fatal("worker refusal corrupted accepted edit")
+	}
+	ls.Close()
+}
