	ls.Lock()
	ls.commitNativeComposition()
	autoSave := ls.batchUpdateStart()
	tbe := ls.redo()
	ls.batchUpdateEnd(autoSave)
	ls.Unlock()
	ls.sendInput()
	return tbe
}

