func TestVellumManualTextCoreMarkupCallbackFaultUnwinds(t *testing.T) {
	for _, kind := range []string{"panic", "goexit"} {
		t.Run(kind, func(t *testing.T) {
			m, ed, _, clock := ownedEditorFixture(t)
			ed.Lines.SetString("{\"a\":1}\n")
			ed.Lines.SetFileExt("json")
			ed.Lines.StopDelayedReMarkup()
			ownedDrain(t, m)
			ed.Lines.OnInput(ed.viewId, func(events.Event) {
				if kind == "goexit" {
					runtime.Goexit()
				}
				panic("parser listener")
			})
			ed.Lines.ReMarkup()
			clock.Advance(0)
			done := make(chan struct{})
			var stepErr error
			go func() { defer close(done); _, stepErr = m.Step(context.Background(), 64) }()
			select {
			case <-done:
			case <-time.After(5 * time.Second):
				t.Fatal("callback ownership did not unwind")
			}
			snap, err := m.Snapshot(context.Background())
			if err != nil || !errors.Is(snap.Failure, core.ErrManualCallback) {
				t.Fatal("fault not terminal", snap, err, stepErr)
			}
			// Buffer and window lock ownership must have unwound before cleanup.
			done = make(chan struct{})
			go func() { defer close(done); ed.Lines.StopDelayedReMarkup(); _ = m.Close(context.Background()) }()
			select {
			case <-done:
			case <-time.After(5 * time.Second):
				t.Fatal("buffer/window remained locked after fault")
			}
		})
	}
}

type refusingReader struct{ reads int }

func (r *refusingReader) Read([]byte) (int, error) {
	r.reads++
	return 0, errors.New("reader should not be touched")
}
func TestVellumManualTextCoreOutputReaderRefusesBeforeRead(t *testing.T) {
	m, ed, _, _ := ownedEditorFixture(t)
	reader := &refusingReader{}
	ob := &OutputBuffer{Lines: ed.Lines, Output: reader}
	ob.MonitorOutput()
	snap, err := m.Snapshot(context.Background())
	if err != nil || !errors.Is(snap.Failure, lines.ErrManualAmbient) || reader.reads != 0 || ob.afterTimer != nil || len(ob.bufferedLines) != 0 {
		t.Fatal("unsupported reader ran ambient work", snap, err, reader.reads)
	}
}

func TestVellumManualTextCoreAmbientReaderFaultReleasesAdoption(t *testing.T) {
	for _, kind := range []string{"panic", "goexit"} {
		t.Run(kind, func(t *testing.T) {
			ls := lines.NewLinesExact()
			view := ls.NewView(80)
			ob := &OutputBuffer{Lines: ls, Output: strings.NewReader("one\n"), MarkupFunc: func(*lines.Lines, []rune) rich.Text {
				if kind == "goexit" {
					runtime.Goexit()
				}
				panic("ambient markup")
			}}
			done := make(chan struct{})
			go func() { defer close(done); defer func() { _ = recover() }(); ob.MonitorOutput() }()
			select {
			case <-done:
			case <-time.After(5 * time.Second):
				t.Fatal("reader fault retained batch mutex/lifetime")
			}
			var failure error
			execution := &lines.ManualExecution{Now: func() time.Time { return time.Unix(1700000000, 0) }, AfterFunc: func(time.Duration, func()) (lines.Timer, error) { return nil, errors.New("unexpected timer") }, Failure: func(err error) { failure = err }}
			if err := ls.BindManualExecution(view, execution); err != nil || failure != nil {
				t.Fatal("reader worker did not retire", err, failure)
			}
			ls.Close()
		})
	}
}

