	hash := sha256.Sum256(invalid.Fonts[0].Data)
	invalid.Fonts[0].SHA256 = hex.EncodeToString(hash[:])
	if _, err = NewManual(testContext, a2, invalid); !errors.Is(err, ErrManualConfig) {
