func TestConcurrentProducersContiguousOrder(t *testing.T) {
	r, _ := NewRecorder(fixture(), Limits{MaxOperations: 1000})
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
