package replay

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"reflect"
	"strings"
	"sync/atomic"
	"time"
	"unicode/utf8"
)

var (
	ErrBusy       = errors.New("replay: concurrent or reentrant run")
	ErrBudget     = errors.New("replay: step budget exhausted")
	ErrNoProgress = errors.New("replay: backend reports ready work without progress")
	ErrBackend    = errors.New("replay: invalid backend result")
	ErrTime       = errors.New("replay: explicit scheduling time mismatch")
)

// Readiness describes the backend's single explicit scheduling clock. Ready
// counts work that Step can dispatch now. Running and Awaiting keep admitted
// work observable, including a selected worker or blocked origin that cannot
// progress through Step. Future timers alone do not prevent current quiescence.
type Readiness struct {
	Now                      time.Time
	Ready, Running, Awaiting int
	Blocked                  bool
	DueTimers, FutureTimers  int
	NextDeadline             time.Time
}

func (r Readiness) QuiescentNow() bool {
	return r.validate() == nil && r.Ready == 0 && r.Running == 0 && r.Awaiting == 0 && r.DueTimers == 0 && !r.Blocked
}
func (r Readiness) validate() error {
	if r.Now.IsZero() || r.Now.Location() != time.UTC || r.Ready < 0 || r.Running < 0 || r.Awaiting < 0 || r.DueTimers < 0 || r.FutureTimers < 0 || r.Ready > 1<<26 || r.Running > 1<<26 || r.Awaiting > 1<<26 || r.DueTimers > 1<<26 || r.FutureTimers > 1<<26 {
		return ErrBackend
	}
	if !r.NextDeadline.IsZero() && r.NextDeadline.Location() != time.UTC {
		return ErrBackend
	}
	if r.DueTimers > 0 {
		if r.NextDeadline.IsZero() || r.NextDeadline.After(r.Now) {
			return ErrBackend
		}
	} else if r.FutureTimers > 0 {
		if r.NextDeadline.IsZero() || !r.NextDeadline.After(r.Now) {
			return ErrBackend
		}
	} else if !r.NextDeadline.IsZero() {
		return ErrBackend
	}
	return nil
}

// Progress counts actual bounded dispatch units. A paint event can count both
// an event and a frame within one unit; category counts need not sum to Units.
type Progress struct{ Units, Events, Owners, Timers, Frames int }

func (p Progress) validate(budget int) error {
	if p.Units < 0 || p.Units > budget {
		return ErrBackend
	}
	for _, n := range []int{p.Events, p.Owners, p.Timers, p.Frames} {
		if n < 0 || n > p.Units {
			return ErrBackend
		}
	}
	return nil
}

// Observation is detached semantic/model/layout JSON and an optional identity
// of an already completed image. Capture must not request a frame or advance
// time. The concrete backend refuses an unrendered or stale image.
type Observation struct {
	Data        json.RawMessage
	ImageSHA256 string
}

// Backend routes through its actual driver. It must check fixture/font/theme
// identities, target/window lifetimes, expected revisions and operation times.
// Step uses one shared explicit clock and never advances it or selects workers.
// Future-only timers and work awaiting explicit operations are reported rather
// than executed implicitly. Methods must honor ctx and their dispatch budgets.
// The runner borrows the backend; its caller owns backend construction/closure.
type Backend interface {
	CheckManifest(context.Context, Manifest) error
	Apply(context.Context, Operation) error
	Readiness(context.Context) (Readiness, error)
	Step(context.Context, int) (Progress, error)
	Capture(context.Context, Operation) (Observation, error)
}

type RunnerConfig struct {
	RecordLimits                                 Limits
	MaxSteps, EventBatch                         int
	MaxCaptures, MaxCaptureBytes, MaxReportBytes int
}

func (c RunnerConfig) normalized() (RunnerConfig, error) {
	var err error
	c.RecordLimits, err = c.RecordLimits.normalized()
	if err != nil {
		return c, err
	}
	if c.MaxSteps == 0 {
		c.MaxSteps = 10000
	}
	if c.EventBatch == 0 {
		c.EventBatch = 64
	}
	if c.MaxCaptures == 0 {
		c.MaxCaptures = 128
	}
	if c.MaxCaptureBytes == 0 {
		c.MaxCaptureBytes = 1 << 20
	}
	if c.MaxReportBytes == 0 {
		c.MaxReportBytes = 8 << 20
	}
	if c.MaxSteps < 1 || c.MaxSteps > 1000000 || c.EventBatch < 1 || c.EventBatch > 4096 || c.MaxCaptures < 1 || c.MaxCaptures > 10000 || c.MaxCaptureBytes < 1 || c.MaxCaptureBytes > 8<<20 || c.MaxReportBytes < 1 || c.MaxReportBytes > 64<<20 || c.MaxCaptureBytes > c.MaxReportBytes {
		return c, ErrInvalid
	}
	return c, nil
}

type Checkpoint struct {
	Sequence      uint64
	Label, Window string
	Data          json.RawMessage
	ImageSHA256   string
}

// Residual is the last successfully inspected readiness, including on error.
// It is not a new observation after a canceled or failed backend call.
type Result struct {
	Applied      int
	Progress     Progress
	Residual     Readiness
	QuiescentNow bool
	Checkpoints  []Checkpoint
}
type IdleResult struct {
	Progress     Progress
	Residual     Readiness
	QuiescentNow bool
}

// Runner admits one run at a time; it has no background loop or hidden sleeps.
// A failed run can have applied a prefix. No model/time rollback is implied.
// The caller supplies context deadlines; this runner cannot preempt a callback
// that ignores its context or make an arbitrary backend operation reversible.
// A run completes its operation list even if it reports explicit pending work.
// Do not copy Runner after construction.
type Runner struct {
	config  RunnerConfig
	backend Backend
	self    *Runner
	busy    atomic.Bool
}

func NewRunner(config RunnerConfig, backend Backend) (*Runner, error) {
	c, err := config.normalized()
	if err != nil {
		return nil, err
	}
	if backend == nil {
		return nil, ErrInvalid
	}
	value := reflect.ValueOf(backend)
	switch value.Kind() {
	case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Pointer, reflect.Slice:
		if value.IsNil() {
			return nil, ErrInvalid
		}
	}
	r := &Runner{config: c, backend: backend}
	r.self = r
	return r, nil
}
func (r *Runner) enter(ctx context.Context) error {
	if r == nil || r.self != r || ctx == nil {
		return ErrInvalid
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if !r.busy.CompareAndSwap(false, true) {
		return ErrBusy
	}
	return nil
}
func (r *Runner) readiness(ctx context.Context) (Readiness, error) {
	if err := ctx.Err(); err != nil {
		return Readiness{}, err
	}
	value, err := r.backend.Readiness(ctx)
	if err != nil {
		return value, err
	}
	return value, value.validate()
}
func addProgress(total *Progress, p Progress) {
	total.Units += p.Units
	total.Events += p.Events
	total.Owners += p.Owners
	total.Timers += p.Timers
	total.Frames += p.Frames
}

func (r *Runner) drain(ctx context.Context, budget int) (IdleResult, error) {
	var out IdleResult
	for {
		before, err := r.readiness(ctx)
		if err != nil {
			return out, err
		}
		out.Residual = before
		out.QuiescentNow = before.QuiescentNow()
		if before.Ready == 0 {
			return out, nil
		}
		if out.Progress.Units >= budget {
			return out, ErrBudget
		}
		quantum := min(r.config.EventBatch, budget-out.Progress.Units)
		p, stepErr := r.backend.Step(ctx, quantum)
		if err := p.validate(quantum); err != nil {
			return out, err
		}
		addProgress(&out.Progress, p)
		// Even a partial failed dispatch is represented in the returned progress.
		if stepErr != nil {
			return out, stepErr
		}
		after, err := r.readiness(ctx)
		if err != nil {
			return out, err
		}
		out.Residual = after
		out.QuiescentNow = after.QuiescentNow()
		if !after.Now.Equal(before.Now) {
			return out, ErrTime
		}
		if p.Units == 0 {
			if after.Ready == 0 || after.Blocked || after.Running > 0 || after.Awaiting > 0 {
				return out, nil
			}
			return out, ErrNoProgress
		}
	}
}

// RunUntilIdle stops at current-instant quiescence or admitted work that needs
// another explicit operation/external completion. Inspect QuiescentNow and the
// residual counts; a future deadline is never advanced to make it true.
func (r *Runner) RunUntilIdle(ctx context.Context) (IdleResult, error) {
	if err := r.enter(ctx); err != nil {
		return IdleResult{}, err
	}
	defer r.busy.Store(false)
	return r.drain(ctx, r.config.MaxSteps)
}

// Run validates and detaches the whole record before the backend sees it. Each
// operation consumes one budget unit, followed by bounded currently ready work.
// A worker/clock operation remains explicit; pending work does not prevent later
// recorded cancellation or worker selection from releasing it.
func (r *Runner) Run(ctx context.Context, record Record) (Result, error) {
	var out Result
	if err := r.enter(ctx); err != nil {
		return out, err
	}
	defer r.busy.Store(false)
	if err := record.Validate(r.config.RecordLimits); err != nil {
		return out, err
	}
	frozen := Record{Manifest: cloneManifest(record.Manifest), Operations: make([]Operation, len(record.Operations))}
	for i, o := range record.Operations {
		frozen.Operations[i] = cloneOperation(o)
	}
	initial, err := r.readiness(ctx)
	if err != nil {
		return out, err
	}
	out.Residual, out.QuiescentNow = initial, initial.QuiescentNow()
	if err := r.backend.CheckManifest(ctx, cloneManifest(frozen.Manifest)); err != nil {
		return out, err
	}
	bound, err := r.readiness(ctx)
	if err != nil {
		return out, err
	}
	out.Residual, out.QuiescentNow = bound, bound.QuiescentNow()
	if !bound.Now.Equal(initial.Now) {
		return out, ErrTime
	}
	reportBytes := 0
	for _, operation := range frozen.Operations {
		if err := ctx.Err(); err != nil {
			return out, err
		}
		if out.Applied+out.Progress.Units >= r.config.MaxSteps {
			return out, ErrBudget
		}
		before, err := r.readiness(ctx)
		if err != nil {
			return out, err
		}
		out.Residual = before
		out.QuiescentNow = before.QuiescentNow()
		if !before.Now.Equal(frozen.Manifest.Start.Add(operation.At)) {
			return out, fmt.Errorf("%w: operation %d timestamp", ErrTime, operation.Sequence)
		}
		if operation.Kind == Capture {
			if len(out.Checkpoints) >= r.config.MaxCaptures {
				return out, ErrCapacity
			}
			capture, err := r.backend.Capture(ctx, cloneOperation(operation))
			if err != nil {
				return out, err
			}
			if len(capture.Data) > r.config.MaxCaptureBytes {
				return out, ErrCapacity
			}
			if !utf8.Valid(capture.Data) || !json.Valid(capture.Data) || capture.ImageSHA256 != "" && !hash(capture.ImageSHA256) {
				return out, ErrBackend
			}
			point := Checkpoint{Sequence: operation.Sequence, Label: strings.Clone(operation.Label), Window: strings.Clone(operation.Window), Data: append(json.RawMessage(nil), capture.Data...), ImageSHA256: strings.Clone(capture.ImageSHA256)}
			// Bound canonical checkpoint bytes, including identity/label overhead.
			encoded, err := json.Marshal(point)
			if err != nil {
				return out, fmt.Errorf("%w: capture encoding", ErrBackend)
			}
			if len(encoded) > r.config.MaxReportBytes-reportBytes {
				return out, ErrCapacity
			}
			reportBytes += len(encoded)
			out.Checkpoints = append(out.Checkpoints, point)
		} else {
			if err := r.backend.Apply(ctx, cloneOperation(operation)); err != nil {
				return out, err
			}
		}
		out.Applied++
		after, err := r.readiness(ctx)
		if err != nil {
			return out, err
		}
		out.Residual = after
		out.QuiescentNow = after.QuiescentNow()
		expected := before.Now
		if operation.Kind == Advance {
			expected = expected.Add(operation.Delta)
		}
		if !after.Now.Equal(expected) {
			return out, ErrTime
		}
		idle, err := r.drain(ctx, r.config.MaxSteps-out.Applied-out.Progress.Units)
		addProgress(&out.Progress, idle.Progress)
		out.Residual = idle.Residual
		out.QuiescentNow = idle.QuiescentNow
		if err != nil {
			return out, err
		}
	}
	if len(frozen.Operations) == 0 {
		idle, err := r.drain(ctx, r.config.MaxSteps)
		out.Progress = idle.Progress
		out.Residual = idle.Residual
		out.QuiescentNow = idle.QuiescentNow
		return out, err
	}
	return out, nil
}

package replay

// This backend tests the runner protocol, bounds and ownership. It does not
// stand in for the separate actual managed widget/router acceptance.
import (
	"context"
	"encoding/json"
	"errors"
	"reflect"
	"strings"
	"testing"
	"time"
)

type protocolBackend struct {
	state      Readiness
	applied    []Operation
	quanta     []int
	dispatched int
	calls      int
	capture    Observation
	check      func(Manifest) error
	apply      func(Operation) error
	step       func(int) (Progress, error)
}

func protocol() *protocolBackend {
	return &protocolBackend{state: Readiness{Now: fixture().Start}, capture: Observation{Data: json.RawMessage(`{"count":1}`), ImageSHA256: strings.Repeat("d", 64)}}
}
func (b *protocolBackend) CheckManifest(_ context.Context, m Manifest) error {
	b.calls++
	if b.check != nil {
		return b.check(m)
	}
	return nil
}
func (b *protocolBackend) Apply(_ context.Context, o Operation) error {
	b.calls++
	b.applied = append(b.applied, o)
	if b.apply != nil {
		return b.apply(o)
	}
	if o.Kind == Advance {
		b.state.Now = b.state.Now.Add(o.Delta)
	} else {
		b.state.Ready += 9
	}
	return nil
}
func (b *protocolBackend) Readiness(context.Context) (Readiness, error) {
	b.calls++
	return b.state, nil
}
func (b *protocolBackend) Step(_ context.Context, n int) (Progress, error) {
	b.calls++
	b.quanta = append(b.quanta, n)
	if b.step != nil {
		return b.step(n)
	}
	count := min(n, b.state.Ready)
	b.state.Ready -= count
	b.dispatched += count
	return Progress{Units: count, Events: count}, nil
}
func (b *protocolBackend) Capture(context.Context, Operation) (Observation, error) {
	b.calls++
	return b.capture, nil
}
func recordWith(operations ...Operation) Record {
	for i := range operations {
		operations[i].Sequence = uint64(i) + 1
	}
	return Record{Manifest: fixture(), Operations: operations}
}

func TestRunnerProtocolBatchesAndExplicitTime(t *testing.T) {
	var expected Result
	for _, batch := range []int{1, 7, 64} {
		b := protocol()
		r, err := NewRunner(RunnerConfig{EventBatch: batch}, b)
		if err != nil {
			t.Fatal(err)
		}
		record := recordWith(action(), Operation{Kind: Advance, Window: "main", WindowIncarnation: 1, Delta: time.Second}, Operation{Kind: Frame, Window: "main", WindowIncarnation: 1, At: time.Second}, Operation{Kind: Capture, Window: "main", WindowIncarnation: 1, At: time.Second, Label: "final"})
		got, err := r.Run(context.Background(), record)
		if err != nil {
			t.Fatal(err)
		}
		if got.Applied != 4 || got.Progress.Units != 18 || b.dispatched != 18 || !got.QuiescentNow || !b.state.Now.Equal(fixture().Start.Add(time.Second)) {
			t.Fatalf("batch %d: %+v", batch, got)
		}
		for _, quantum := range b.quanta {
			if quantum < 1 || quantum > batch {
				t.Fatal("unbounded quantum", quantum)
			}
		}
		if batch == 1 {
			expected = got
		} else if !reflect.DeepEqual(expected, got) {
			t.Fatalf("batch %d differs", batch)
		}
	}
}
func TestRunnerFutureOnlyAndUnreadyWorkRemainVisible(t *testing.T) {
	for _, kind := range []string{"future", "due", "running", "awaiting", "blocked"} {
		t.Run(kind, func(t *testing.T) {
			b := protocol()
			switch kind {
			case "future":
				b.state.FutureTimers = 2
				b.state.NextDeadline = b.state.Now.Add(time.Hour)
			case "due":
				b.state.DueTimers = 1
				b.state.NextDeadline = b.state.Now
			case "running":
				b.state.Running = 1
			case "awaiting":
				b.state.Awaiting = 1
			case "blocked":
				b.state.Ready = 4
				b.state.Blocked = true
				b.step = func(int) (Progress, error) { return Progress{}, nil }
			}
			r, _ := NewRunner(RunnerConfig{}, b)
			got, err := r.RunUntilIdle(context.Background())
			if err != nil {
				t.Fatal(err)
			}
			if got.QuiescentNow != (kind == "future") || !got.Residual.Now.Equal(fixture().Start) || got.Progress.Units != 0 {
				t.Fatal(got)
			}
			if kind != "blocked" && len(b.quanta) != 0 {
				t.Fatal("hidden step")
			}
		})
	}
	if (Readiness{}).QuiescentNow() {
		t.Fatal("uninitialized state called quiescent")
	}
}
func TestRunnerCanCancelAndSelectAwaitingWorkerExplicitly(t *testing.T) {
	b := protocol()
	b.apply = func(o Operation) error {
		switch o.Action {
		case "start":
			b.state.Awaiting = 1
		case "cancel":
			if b.state.Awaiting != 1 {
				t.Fatal("missing admitted work")
			}
		}
		if o.Kind == Worker {
			b.state.Awaiting = 0
			b.state.Ready = 1
		}
		return nil
	}
	r, _ := NewRunner(RunnerConfig{}, b)
	start := action()
	start.Action = "start"
	cancel := action()
	cancel.Action = "cancel"
	got, err := r.Run(context.Background(), recordWith(start, cancel, Operation{Kind: Worker, WorkerID: 7}))
	if err != nil || got.Applied != 3 || got.Progress.Units != 1 || !got.QuiescentNow || len(b.applied) != 3 {
		t.Fatal(got, err)
	}
}
func TestRunnerBoundsRefuseBeforeBackendAndReportAppliedPrefix(t *testing.T) {
	b := protocol()
	r, _ := NewRunner(RunnerConfig{MaxSteps: 2}, b)
	bad := action()
	bad.Action = "bad\x00"
	if _, err := r.Run(context.Background(), recordWith(action(), bad)); !errors.Is(err, ErrInvalid) || b.calls != 0 {
		t.Fatal("invalid record reached backend", err, b.calls)
	}
	got, err := r.Run(context.Background(), recordWith(action()))
	if !errors.Is(err, ErrBudget) || got.Applied != 1 || got.Progress.Units != 1 || got.Residual.Ready != 8 || got.QuiescentNow {
		t.Fatal(got, err)
	}
}
func TestRunnerRecordAndCaptureStorageAreDetached(t *testing.T) {
	b := protocol()
	record := recordWith(action(), Operation{Kind: Capture, Window: "main", WindowIncarnation: 1, Label: "before"}, action())
	b.check = func(m Manifest) error {
		m.Fonts[0].Family = "backend mutation"
		record.Operations[0].Action = "caller mutation"
		record.Operations[0].Arguments[0].Value = "caller mutation"
		return nil
	}
	b.apply = func(o Operation) error {
		if len(b.applied) == 2 {
			b.capture.Data[9] = '2'
		}
		return nil
	}
	r, _ := NewRunner(RunnerConfig{}, b)
	got, err := r.Run(context.Background(), record)
	if err != nil || len(b.applied) != 2 || b.applied[0].Action != "save" || b.applied[0].Arguments[0].Value != "A😀\r\n" || string(got.Checkpoints[0].Data) != `{"count":1}` {
		t.Fatal(got, err, b.applied)
	}
	got.Checkpoints[0].Data[9] = '3'
	if string(b.capture.Data) != `{"count":2}` {
		t.Fatal("result data aliases backend")
	}
}
func TestRunnerCaptureBudgetsAndInvalidData(t *testing.T) {
	capture := Operation{Kind: Capture, Window: "main", WindowIncarnation: 1, Label: "sample"}
	b := protocol()
	point := Checkpoint{Sequence: 1, Window: "main", Label: "sample", Data: b.capture.Data, ImageSHA256: b.capture.ImageSHA256}
	encoded, _ := json.Marshal(point)
	for _, which := range []string{"exact", "report-byte", "payload-byte", "count", "json", "hash", "utf8"} {
		t.Run(which, func(t *testing.T) {
			b := protocol()
			config := RunnerConfig{MaxCaptureBytes: len(b.capture.Data), MaxReportBytes: len(encoded)}
			record := recordWith(capture)
			switch which {
			case "report-byte":
				config.MaxReportBytes--
			case "payload-byte":
				config.MaxCaptureBytes--
			case "count":
				config.MaxCaptures = 1
				record = recordWith(capture, capture)
			case "json":
				b.capture.Data = json.RawMessage(`{`)
			case "hash":
				b.capture.ImageSHA256 = "bad"
			case "utf8":
				b.capture.Data = json.RawMessage{0xff}
			}
			r, err := NewRunner(config, b)
			if err != nil {
				t.Fatal(err)
			}
			got, err := r.Run(context.Background(), record)
			if which == "exact" {
				if err != nil || len(got.Checkpoints) != 1 {
					t.Fatal(got, err)
				}
				return
			}
			want := ErrCapacity
			if which == "json" || which == "hash" || which == "utf8" {
				want = ErrBackend
			}
			if !errors.Is(err, want) {
				t.Fatal(which, got, err)
			}
			if which != "count" && len(got.Checkpoints) != 0 {
				t.Fatal("refused capture retained")
			}
		})
	}
}
func TestRunnerRefusesHiddenTimeAndImpossibleProgress(t *testing.T) {
	for _, which := range []string{"manifest-time", "operation-time", "step-time", "record-time", "overspend", "negative", "category", "no-progress", "invalid-readiness"} {
		t.Run(which, func(t *testing.T) {
			b := protocol()
			record := recordWith(action())
			want := ErrBackend
			switch which {
			case "manifest-time":
				b.check = func(Manifest) error { b.state.Now = b.state.Now.Add(time.Second); return nil }
				want = ErrTime
			case "operation-time":
				b.apply = func(Operation) error { b.state.Now = b.state.Now.Add(time.Second); return nil }
				want = ErrTime
			case "step-time":
				b.step = func(int) (Progress, error) {
					b.state.Now = b.state.Now.Add(time.Second)
					return Progress{Units: 1}, nil
				}
				want = ErrTime
			case "record-time":
				record.Operations[0].At = time.Second
				want = ErrTime
			case "overspend":
				b.step = func(n int) (Progress, error) { return Progress{Units: n + 1}, nil }
			case "negative":
				b.step = func(int) (Progress, error) { return Progress{Units: -1}, nil }
			case "category":
				b.step = func(int) (Progress, error) { return Progress{Units: 1, Frames: 2}, nil }
			case "no-progress":
				b.step = func(int) (Progress, error) { return Progress{}, nil }
				want = ErrNoProgress
			case "invalid-readiness":
				b.state.FutureTimers = 1
			}
			r, _ := NewRunner(RunnerConfig{}, b)
			_, err := r.Run(context.Background(), record)
			if !errors.Is(err, want) {
				t.Fatal(which, err)
			}
		})
	}
}
func TestRunnerCancellationAndReentrantAdmission(t *testing.T) {
	b := protocol()
	b.state.Ready = 2
	r, _ := NewRunner(RunnerConfig{}, b)
	canceled, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := r.RunUntilIdle(canceled); !errors.Is(err, context.Canceled) || b.calls != 0 {
		t.Fatal(err, b.calls)
	}
	if _, err := r.Run(nil, recordWith(action())); !errors.Is(err, ErrInvalid) {
		t.Fatal(err)
	}
	b.step = func(int) (Progress, error) {
		if _, err := r.RunUntilIdle(context.Background()); !errors.Is(err, ErrBusy) {
			t.Fatal(err)
		}
		b.state.Ready = 0
		return Progress{Units: 2, Events: 2}, nil
	}
	if got, err := r.RunUntilIdle(context.Background()); err != nil || !got.QuiescentNow {
		t.Fatal(got, err)
	}
	b.state.Ready = 2
	ctx, cancel := context.WithCancel(context.Background())
	b.step = func(int) (Progress, error) { cancel(); b.state.Ready--; return Progress{Units: 1}, ctx.Err() }
	got, err := r.RunUntilIdle(ctx)
	if !errors.Is(err, context.Canceled) || got.Progress.Units != 1 || got.Residual.Ready != 2 || got.QuiescentNow {
		t.Fatal(got, err)
	}
}
func TestRunnerConcurrentAndCopiedAdmission(t *testing.T) {
	b := protocol()
	b.state.Ready = 1
	r, _ := NewRunner(RunnerConfig{}, b)
	copyValue := reflect.New(reflect.TypeOf(r).Elem())
	copyValue.Elem().Set(reflect.ValueOf(r).Elem())
	copied := copyValue.Interface().(*Runner)
	if _, err := copied.RunUntilIdle(context.Background()); !errors.Is(err, ErrInvalid) {
		t.Fatal(err)
	}
	entered, release, done := make(chan struct{}), make(chan struct{}), make(chan error, 1)
	b.step = func(int) (Progress, error) {
		close(entered)
		<-release
		b.state.Ready = 0
		return Progress{Units: 1}, nil
	}
	go func() { _, err := r.RunUntilIdle(context.Background()); done <- err }()
	<-entered
	if _, err := r.Run(context.Background(), recordWith(action())); !errors.Is(err, ErrBusy) {
		t.Fatal(err)
	}
	close(release)
	if err := <-done; err != nil {
		t.Fatal(err)
	}
}

