func TestNativeManifestAndLiveRevisionRefusals(t *testing.T) {
	b := nativeFixture(t, 1)
	r, err := replay.NewRunner(replay.RunnerConfig{}, b)
	if err != nil {
		t.Fatal(err)
	}
